import {uniquePairs} from './memory-engine.js';
export const DIRECTIONS=[[0,-1],[1,0],[0,1],[-1,0]];
export class MazeGame{
 constructor(pack,{random=Math.random}={}){this.pack=uniquePairs(pack);if(this.pack.length<4)throw Error('異なる訳の単語を4組以上入れてください。');this.random=random;this.player={x:1,y:1};this.enemies=[{x:7,y:1},{x:1,y:7},{x:7,y:7}];this.grid=Array.from({length:9},(_,y)=>Array.from({length:9},(_,x)=>x===0||y===0||x===8||y===8||x%2===0&&y%2===0?1:0));const safe=new Set(['1,1','1,2','2,1','1,3','3,1','3,2','2,3','7,1','1,7','7,7']);for(let y=1;y<8;y++)for(let x=1;x<8;x++)if(!this.grid[y][x]&&!safe.has(x+','+y)&&random()<.38)this.grid[y][x]=2;this.bombs=[];this.flames=[];this.ammo=1;this.hp=3;this.time=150;this.cooldown=0;this.invincible=0;this.enemyClock=0;this.mode='play';this.quiz=null;this.qIndex=0;this.correct=0;this.answered=0;this.destroyed=0;this.kills=0;this.review=new Map();}
 blocked(x,y){return !this.grid[y]||this.grid[y][x]!==0||this.bombs.some(b=>b.x===x&&b.y===y);}
 move(dx,dy){if(this.mode!=='play'||this.quiz||this.cooldown>0||Math.abs(dx)+Math.abs(dy)!==1)return false;const x=this.player.x+dx,y=this.player.y+dy;if(this.blocked(x,y))return false;this.player={x,y};this.cooldown=.15;this.check();return true;}
 place(){if(this.mode!=='play'||this.quiz||this.ammo<1||this.bombs.length>=2||this.bombs.some(b=>b.x===this.player.x&&b.y===this.player.y))return false;this.ammo--;this.bombs.push({...this.player,life:2.4});return true;}
 openQuiz(){if(this.mode!=='play'||this.quiz||this.ammo>=4)return false;const target=this.pack[this.qIndex++%this.pack.length],others=this.pack.filter(p=>p!==target);const choices=[target,...others.slice(0,2)];for(let i=choices.length-1;i;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]];}this.quiz={target,choices,answered:false,result:null};return true;}
 answerQuiz(index){if(!this.quiz||this.quiz.answered||!Number.isInteger(index)||index<0||index>=3)return null;this.answered++;this.quiz.answered=true;const ok=this.quiz.choices[index]===this.quiz.target;this.quiz.result=ok;if(ok){this.correct++;this.ammo=Math.min(4,this.ammo+2);}else this.review.set(this.quiz.target.word,this.quiz.target);return ok;}
 closeQuiz(){this.quiz=null;}
 explode(b){if(!this.bombs.includes(b))return;this.bombs=this.bombs.filter(a=>a!==b);const cells=[{x:b.x,y:b.y}];for(const[dx,dy]of DIRECTIONS)for(let n=1;n<=2;n++){const x=b.x+dx*n,y=b.y+dy*n;if(!this.grid[y]||this.grid[y][x]===1)break;cells.push({x,y});if(this.grid[y][x]===2){this.grid[y][x]=0;this.destroyed++;break;}}for(const c of cells)this.flames.push({...c,life:.65});for(const other of [...this.bombs])if(cells.some(c=>c.x===other.x&&c.y===other.y))this.explode(other);}
 check(){if(this.mode!=='play')return;const hit=(p)=>this.flames.some(f=>f.x===p.x&&f.y===p.y);const dead=this.enemies.filter(hit);this.kills+=dead.length;this.enemies=this.enemies.filter(e=>!hit(e));if(this.invincible<=0&&(hit(this.player)||this.enemies.some(e=>e.x===this.player.x&&e.y===this.player.y))){this.hp--;this.invincible=1.3;if(this.hp<=0)this.mode='lost';}if(this.mode==='play'&&!this.enemies.length&&this.player.x===7&&this.player.y===7)this.mode='won';}
 tick(dt){if(this.mode!=='play'||this.quiz||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,.1);this.time=Math.max(0,this.time-dt);if(!this.time){this.mode='lost';return;}this.cooldown=Math.max(0,this.cooldown-dt);this.invincible=Math.max(0,this.invincible-dt);this.flames=this.flames.filter(f=>(f.life-=dt)>0);for(const b of [...this.bombs]){b.life-=dt;if(b.life<=0)this.explode(b);}this.check();if(this.mode!=='play')return;this.enemyClock+=dt;if(this.enemyClock>=.65){this.enemyClock=0;for(const e of this.enemies){const choices=DIRECTIONS.filter(([dx,dy])=>!this.blocked(e.x+dx,e.y+dy));if(choices.length){const[dx,dy]=choices[Math.floor(this.random()*choices.length)];e.x+=dx;e.y+=dy;}}this.check();}}
}
